<template><section class="module-page module-composed-page"><header class="module-heading"><h1>运维主页</h1><p>处理服务器、容器模板和镜像仓库的运行状态。</p></header><section class="metric-strip"><div><small>处理服务器</small><strong>{{ agents }}</strong><span>已接入服务器</span></div><div><small>在线服务器</small><strong>{{ online }}</strong><span>最近心跳在线</span></div><div><small>容器模板</small><strong>{{ templates }}</strong><span>可用模板版本</span></div><div><small>镜像仓库</small><strong>已配置</strong><span>版本化镜像管理</span></div></section><section class="module-context-band"><div><small>当前权限</small><strong>系统运维</strong></div><nav class="module-toolbar" aria-label="常用运维入口"><router-link class="el-button el-button--primary" to="/operations/processing-agents">处理服务器</router-link><router-link class="el-button" to="/operations/container-templates">容器模板</router-link><router-link class="el-button" to="/operations/image-registry">镜像仓库</router-link><router-link class="el-button" to="/operations/administrators">管理员账号</router-link></nav></section></section></template>
<script>
import { listProcessingAgents } from '@/api/ProcessingAgents'
import { listContainerTemplates } from '@/api/ContainerTemplates'
export default { data:()=>({agents:0,online:0,templates:0}), async created(){try{const [a,t]=await Promise.all([listProcessingAgents(),listContainerTemplates()]);const rows=a.data||[];this.agents=rows.length;this.online=rows.filter(x=>x.online).length;this.templates=(t.data||[]).filter(x=>x.enabled).length}catch(e){}}}
</script>
